const compiled=await rpc(1,'tools/call',{name:'compile_history',arguments:{}});
const prsRes=await fetch('https://api.github.com/repos/timoygeroin/T-mo-y-i-c-n-y-c-r-t-g-r-a-i-n-a-/pulls?state=open&per_page=100',{headers:{'user-agent':'mondayid-project-zero-proof'}});
const prs=await prsRes.json();
const v=compiled?.json?.result?.structuredContent;
const ok=compiled.status===200 && v?.ok===true && v?.compiled?.projectRuntimeAuthority===false && v?.compiled?.totalValid>=55 && Array.isArray(prs) && prs.length===0;
const proof={ok,marker:ok?'project-zero-live-ok':'project-zero-live-fail',totalValid:v?.compiled?.totalValid,uniqueEffects:v?.compiled?.uniqueEffects,compression:v?.compiled?.compression,openPullRequests:Array.isArray(prs)?prs.length:null,activeOrgans:v?.delta?.activeOrgans,activeRoles:v?.delta?.activeRoles,externalGates:v?.delta?.externalGates};
await fs.writeFile('project-zero-live.json',JSON.stringify(proof));console.log(JSON.stringify(proof));if(!ok) process.exitCode=2;
